13	/// Renders an [AsyncValue] without every screen repeating the four states.
14	/// Generic over the loaded type, so one widget serves lists and single objects.
15	class AsyncView<T> extends StatelessWidget {
16	  const AsyncView({
17	    super.key,
18	    required this.value,
19	    required this.builder,
20	    this.onRetry,
21	    this.emptyLabel,
22	    this.isEmpty,
23	  });
24	
25	  final AsyncValue<T> value;
26	  final Widget Function(T data) builder;
27	  final VoidCallback? onRetry;
28	  final String? emptyLabel;
29	  final bool Function(T data)? isEmpty;
30	
31	  @override
32	  Widget build(BuildContext context) => value.when(
33	        data: (data) {
34	          if (isEmpty?.call(data) ?? false) {
35	            return EmptyView(label: emptyLabel ?? 'Nothing here yet.', onRetry: onRetry);
36	          }
37	          return builder(data);
38	        },
39	        loading: () => const LoadingView(),
40	        error: (error, _) => ErrorView(message: messageFor(error), onRetry: onRetry),
41	      );
42	}
