10	/// Matches list. Spec 1.2 — this stays reachable when a subscription lapses.
11	class MatchesScreen extends ConsumerWidget {
12	  const MatchesScreen({super.key});
13	
14	  @override
15	  Widget build(BuildContext context, WidgetRef ref) {
16	    final matches = ref.watch(matchesProvider);
17	
18	    return Scaffold(
19	      appBar: AppBar(title: const Text('Matches')),
20	      body: AsyncView(
21	        value: matches,
22	        onRetry: () => ref.invalidate(matchesProvider),
23	        isEmpty: (list) => list.isEmpty,
24	        emptyLabel: 'No matches yet. Keep browsing — a mutual like starts a chat.',
25	        builder: (list) => RefreshIndicator(
26	          onRefresh: () => ref.read(matchesProvider.notifier).reload(),
27	          child: ListView.separated(
28	            itemCount: list.length,
29	            separatorBuilder: (_, __) => const Divider(height: 1),
30	            itemBuilder: (context, i) => _MatchTile(match: list[i]),
31	          ),
32	        ),
33	      ),
34	    );
35	  }
36	}
