13	/// Spec 1.2 — live selfie capture, in-app camera only.
14	///
15	/// The gallery is not merely hidden here, it is unreachable: this widget holds a
16	/// [CameraController] and renders its preview with a shutter. There is no image
17	/// picker in this file, so no code path can substitute a stored photo.
18	class SelfieScreen extends ConsumerStatefulWidget {
19	  const SelfieScreen({super.key, required this.onDone});
20	
21	  final VoidCallback onDone;
22	
23	  @override
24	  ConsumerState<SelfieScreen> createState() => _SelfieScreenState();
25	}
