27	class _SelfieScreenState extends ConsumerState<SelfieScreen>
28	    with WidgetsBindingObserver, FormProgress {
29	  CameraController? _camera;
30	  String? _sessionId;
31	
32	  @override
33	  void initState() {
34	    super.initState();
35	    WidgetsBinding.instance.addObserver(this);
36	    _start();
37	  }
38	
39	  @override
40	  void dispose() {
41	    WidgetsBinding.instance.removeObserver(this);
42	    _camera?.dispose();
43	    super.dispose();
44	  }
45	
46	  @override
47	  void didChangeAppLifecycleState(AppLifecycleState state) {
48	    final camera = _camera;
49	    if (camera == null || !camera.value.isInitialized) return;
50	    // The OS reclaims the camera when the app backgrounds; re-init on return.
51	    if (state == AppLifecycleState.inactive) {
52	      camera.dispose();
53	    } else if (state == AppLifecycleState.resumed) {
54	      _start();
55	    }
56	  }
