58	  Future<void> _start() async {
59	    try {
60	      final cameras = await availableCameras();
61	      if (cameras.isEmpty) throw CameraException('no_camera', 'No camera on this device');
62	      final front = cameras.firstWhere(
63	        (c) => c.lensDirection == CameraLensDirection.front,
64	        orElse: () => cameras.first,
65	      );
66	      final controller = CameraController(front, ResolutionPreset.medium, enableAudio: false);
67	      await controller.initialize();
68	      if (!mounted) {
69	        await controller.dispose();
70	        return;
71	      }
72	      setState(() => _camera = controller);
73	      await _openLivenessSession();
74	    } on CameraException catch (e) {
75	      if (mounted) {
76	        fail(e.code == 'CameraAccessDenied'
77	            ? 'Camera access is needed to verify you. Enable it in Settings and try again.'
78	            : 'Could not start the camera.');
79	      }
80	    }
81	  }
