83	  /// Server-side liveness session. The face-match runs against its reference
84	  /// image, so a session must exist before a selfie is worth submitting.
85	  Future<void> _openLivenessSession() async {
86	    try {
87	      final res = await ref.read(apiProvider).post<Map<String, dynamic>>(
88	        '/verification/liveness-session',
89	        parse: (j) => j as Map<String, dynamic>,
90	      );
91	      if (mounted) setState(() => _sessionId = res['sessionId'] as String?);
92	    } catch (e) {
93	      // Non-fatal: the development passthrough has no session to open.
94	      if (mounted) setState(() => _sessionId = null);
95	    }
96	  }
