98	  Future<void> _capture() async {
99	    final camera = _camera;
100	    if (camera == null || !camera.value.isInitialized) return;
101	
102	    await progress(() async {
103	      final shot = await camera.takePicture();
104	      final userId = ref.read(myProfileProvider).valueOrNull?.userId ?? 'unknown';
105	      final url = await Storage.upload(Storage.pathFor(userId, 'selfies'), File(shot.path));
106	
107	      await ref.read(verificationProvider.notifier).submit(
108	            livenessSessionId: _sessionId,
109	            selfieUrl: url,
110	          );
111	
112	      final result = ref.read(verificationProvider).valueOrNull;
113	      if (!mounted) return;
114	      if (result?.isVerified ?? false) {
115	        widget.onDone();
116	      } else {
117	        fail('We could not verify that photo. Make sure your face is well lit and clearly visible.');
118	      }
119	    });
120	  }
121	
