124	    final camera = _camera;
125	
126	    return Scaffold(
127	      appBar: AppBar(title: const Text('Verify it’s you')),
128	      body: Column(
129	        children: [
130	          Expanded(
131	            child: ColoredBox(
132	              color: Theme.of(context).colorScheme.surfaceContainerHighest,
133	              child: camera == null || !camera.value.isInitialized
