148	                  textAlign: TextAlign.center,
149	                  style: Theme.of(context).textTheme.bodyMedium,
150	                ),
151	                const SizedBox(height: Tokens.spaceMd),
152	                if (error != null) ...[
153	                  ErrorText(error!, textAlign: TextAlign.center),
154	                  const SizedBox(height: Tokens.spaceSm),
155	                ],
